import{_ as t,o,c as a,a2 as d}from"./chunks/framework.BGlkWkwp.js";const m=JSON.parse('{"title":"Row","description":"","frontmatter":{},"headers":[],"relativePath":"components/row.md","filePath":"components/row.md"}'),r={name:"components/row.md"};function n(s,e,i,c,h,l){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="row" tabindex="-1">Row <a class="header-anchor" href="#row" aria-label="Permalink to &quot;Row&quot;">​</a></h1><p>Row is the horizontal layout: items side by side, centred on one line.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it for an icon and its text (gap 2xs), a group of controls (sm, the default), groups of controls (lg) and borderless icon buttons (0, their hit area is the space). Text shrinks and wraps inside the width it is left, while icons, marks and controls keep their size. A row of controls that may not fit takes <code>wrap</code>.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>gap</code></td><td><code>sm</code></td><td><code>0</code>, <code>2xs</code>, <code>sm</code>, <code>md</code> or <code>lg</code></td></tr><tr><td><code>between</code></td><td><code>false</code></td><td>Pushes the first and last items to the two ends</td></tr><tr><td><code>wrap</code></td><td><code>false</code></td><td>Moves items that do not fit to the next line</td></tr><tr><td><code>align</code></td><td><code>center</code></td><td><code>start</code>, <code>end</code> or <code>stretch</code></td></tr><tr><td><code>justify</code></td><td><code>start</code></td><td><code>end</code> moves the whole run to the right end</td></tr><tr><td><code>children</code></td><td>required</td><td>The content</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>Row has no height, padding or line. Marks never shrink; in a row that wraps no item shrinks, and items move to the next line whole. A caption or paragraph at the end of a row takes the rest of the width. At the edge of a container all the text in a row is trimmed to its ink, so that the items of one line stay level.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/row/" title="Row" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/row/" target="_blank" rel="noopener">Row</a></figcaption></figure>',10)])])}const f=t(r,[["render",n]]);export{m as __pageData,f as default};
